# -*- coding: utf-8 -*-
from __future__ import annotations
import base64, hashlib, os, py_compile, shutil, sys, tempfile
from datetime import datetime
from pathlib import Path

TITLE = "CHUẨN HÓA ĐẾM DUY NHẤT OPERATION QĐ3805 TRONG SÁP NHẬP TOÀN CẤP"
EMBEDDED_FILES = {'app/services/school_merger_level_batch_service.py': '', 'app/templates/data_tools/school_merger_level_batch.html': ''}
TARGET_MARKERS = {
    "app/services/school_merger_level_batch_service.py": ["qd3805_level_lock.json", "registry_action_expected_count", "duplicate_mappings"],
    "app/templates/data_tools/school_merger_level_batch.html": ["GIỮ NGUYÊN THEO QĐ3805", "LIÊN CẤP/ĐẶC THÙ"],
}

def locate_root():
    for c in (Path.cwd(), Path(r"C:\PhoCap"), Path(__file__).resolve().parent):
        if (c / "app" / "main.py").exists() and (c / "data" / "phocap.db").exists():
            return c.resolve()
    raise RuntimeError(r"Không tìm thấy dự án C:\PhoCap.")

def db_fingerprint(db: Path):
    h=hashlib.sha256(); found=False
    for p in (db, Path(str(db)+"-wal")):
        if p.exists():
            found=True; h.update(p.name.encode())
            with p.open('rb') as f:
                for c in iter(lambda:f.read(1024*1024), b''):
                    h.update(c)
    return h.hexdigest() if found else 'MISSING'

def atomic_write(path: Path, data: bytes):
    path.parent.mkdir(parents=True, exist_ok=True)
    fd,tmp=tempfile.mkstemp(prefix=path.name+'.',suffix='.tmp',dir=str(path.parent))
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(data); f.flush(); os.fsync(f.fileno())
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp): os.remove(tmp)

def main():
    root=locate_root(); db=root/'data'/'phocap.db'; before=db_fingerprint(db)
    stamp=datetime.now().strftime('%Y%m%d_%H%M%S')
    backup=root/'backups'/f'backup_truoc_chuan_hoa_dem_qd3805_{stamp}'
    changed=[]
    print('='*112); print(TITLE); print('Dự án:',root); print('Database:',db); print('Nguyên tắc: KHÔNG thực hiện sáp nhập; KHÔNG chủ động ghi phocap.db.'); print('='*112)
    try:
        # Chỉ nhận đúng nền đã tích hợp QĐ3805, không khóa SHA cứng để tránh lỗi do khác biệt whitespace/template nhỏ.
        for rel, markers in TARGET_MARKERS.items():
            p=root/rel
            if not p.exists(): raise RuntimeError(f'Thiếu tệp nền: {rel}')
            txt=p.read_text(encoding='utf-8',errors='replace')
            miss=[m for m in markers if m not in txt]
            if miss: raise RuntimeError(f'Tệp {rel} chưa đúng nền tích hợp QĐ3805; thiếu marker: {miss}')
        backup.mkdir(parents=True,exist_ok=True)
        for rel,b64 in EMBEDDED_FILES.items():
            src=root/rel; dst=backup/rel; dst.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(src,dst); changed.append(rel)
            atomic_write(src,base64.b64decode(b64))
        py_compile.compile(str(root/'app/services/school_merger_level_batch_service.py'),doraise=True)
        # Smoke tĩnh: bảo đảm logic duy nhất operation và nhãn cảnh báo đã vào nền.
        svc=(root/'app/services/school_merger_level_batch_service.py').read_text(encoding='utf-8')
        tpl=(root/'app/templates/data_tools/school_merger_level_batch.html').read_text(encoding='utf-8')
        required=[
            'action_state_by_op',
            'registry_duplicate_mapping_count',
            'duplicate_mappings đã được quy về BLOCK đúng một operation',
        ]
        for m in required:
            if m not in svc: raise RuntimeError('Smoke service thiếu marker: '+m)
        if 'CẢNH BÁO TRÙNG GHÉP' not in tpl:
            raise RuntimeError('Smoke template chưa có cảnh báo trùng ghép.')
        after=db_fingerprint(db)
        if after!=before: raise RuntimeError('Database thay đổi trong lúc cài. Dừng và khôi phục mã nguồn.')
        print(); print('='*112)
        print('CÀI ĐẶT THÀNH CÔNG - ĐÃ CHUẨN HÓA KPI THEO OPERATION QĐ3805 DUY NHẤT')
        print('Database: KHÔNG THAY ĐỔI')
        print('Thay đổi: mỗi operation QĐ3805 chỉ được tính đúng 1 lần trong DONE/ĐẠT/CHẶN.')
        print('Nếu một operation ghép vào nhiều phương án nội bộ: tự chuyển BLOCK, hiện cảnh báo và không được chạy.')
        print('Không còn cộng trùng duplicate_mappings vào tổng CHẶN.')
        print('Backup mã nguồn:',backup)
        print('='*112)
    except Exception as e:
        # rollback toàn bộ tệp đã chạm
        if backup.exists():
            for rel in changed:
                b=backup/rel; p=root/rel
                if b.exists(): shutil.copy2(b,p)
        print(); print('='*112)
        print('DỪNG AN TOÀN - CHUẨN HÓA ĐẾM QĐ3805')
        print('Mã nguồn đã được khôi phục nếu đã chạm file.')
        print('Lỗi:',e)
        print('Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.')
        print('='*112)
        raise SystemExit(1)

if __name__=='__main__': main()
